const response = $input.first().json;
const posts = Array.isArray(response) ? response : (response.data || []);

// Generate GeoJSON FeatureCollection for mapping & partner GIS systems
const geoFeatures = posts.map(post => ({
  type: "Feature",
  geometry: {
    type: "Point",
    coordinates: [post.longitude || 0.0, post.latitude || 0.0]
  },
  properties: {
    case_id: post.id || post.case_id,
    child_name: post.title || post.child_name,
    age: post.age,
    gender: post.gender,
    last_seen_location: post.address || post.last_seen_location,
    case_url: `https://kidnap-children.org/posts/${post.id}`,
    image_url: post.image ? `https://kidnap-children.org/uploads/posts/${post.image}` : null,
    created_at: post.created_at
  }
}));

const geoJsonFeed = {
  type: "FeatureCollection",
  generated_at: new Date().toISOString(),
  total_cases: geoFeatures.length,
  features: geoFeatures
};

// Generate Standardized JSON Feed (https://jsonfeed.org/version/1.1)
const jsonFeed = {
  version: "https://jsonfeed.org/version/1.1",
  title: "Kidnap-Children Urgent Missing Child Feed",
  home_page_url: "https://kidnap-children.org",
  feed_url: "https://kidnap-children.org/api/syndication/feed.json",
  description: "Live broadcast feed of active missing child posts for authorized partner networks.",
  expired: false,
  items: posts.map(post => ({
    id: String(post.id),
    url: `https://kidnap-children.org/posts/${post.id}`,
    title: `URGENT: ${post.title || post.child_name}`,
    content_text: post.description || post.content,
    image: post.image ? `https://kidnap-children.org/uploads/posts/${post.image}` : null,
    date_published: post.created_at,
    tags: ["missing_child", "urgent_alert"]
  }))
};

return [{
  json: {
    geoJsonFeed,
    jsonFeed,
    total_active_cases: posts.length,
    updated_at: new Date().toISOString()
  }
}];
